/* 2026-07-29 roaming pet movement fix */
/* The parent only translates. Labels never inherit the sprite's facing flip. */
.roaming-pet{
  width:78px;
  height:104px;
  transition-property:transform;
  transition-timing-function:linear;
  transform-origin:center bottom;
}
.roaming-pet .pet-label{
  position:relative;
  z-index:2;
  transform:translateX(-24%)!important;
  direction:ltr;
  unicode-bidi:plaintext;
}
.roaming-pet .pet-label b,
.roaming-pet .pet-label small{
  transform:none!important;
  direction:ltr;
  unicode-bidi:plaintext;
}
.roaming-pet .pet-sprite{
  --pet-facing:1;
  width:68px;
  height:68px;
  display:grid;
  place-items:end center;
  transform:scaleX(var(--pet-facing));
  transform-origin:center bottom;
  will-change:transform;
}
.roaming-pet .pet-sprite img{
  width:64px;
  height:64px;
  object-fit:contain;
  image-rendering:pixelated;
  filter:drop-shadow(0 4px 3px rgba(0,0,0,.65));
  animation:none!important;
  transform-origin:center bottom;
}
.roaming-pet.pet-is-walking .pet-sprite img{
  animation:petNaturalSteps .34s steps(2,end) infinite!important;
}
@keyframes petNaturalSteps{
  0%{transform:translateY(0) scaleY(1) scaleX(1)}
  50%{transform:translateY(-3px) scaleY(.96) scaleX(1.025)}
  100%{transform:translateY(0) scaleY(1) scaleX(1)}
}
/* Small ground shadow makes the pet look planted rather than hovering. */
.roaming-pet .pet-sprite:after{
  content:"";
  grid-area:1/1;
  align-self:end;
  width:42px;
  height:8px;
  border-radius:50%;
  background:rgba(0,0,0,.28);
  filter:blur(1px);
  transform:translateY(3px);
  z-index:-1;
}
@media(max-width:650px){
  .roaming-pet{width:66px;height:90px}
  .roaming-pet .pet-sprite{width:58px;height:58px}
