/* 2026-07-29 navigation sizing and enabled-state fix */
.game-strip{
  width:min(1510px,calc(100% - 24px));
  max-width:none;
  box-sizing:border-box;
  display:grid;
  grid-template-columns:minmax(190px,1.55fr) repeat(5,minmax(112px,1fr));
  align-items:stretch;
  gap:9px;
  padding:12px;
}
.game-strip>div{
  min-width:0;
  margin:0;
  justify-content:center;
  padding:0 8px;
}
.game-strip>div span{
  line-height:1.25;
  overflow-wrap:anywhere;
}
.game-strip button{
  width:100%;
  min-width:0!important;
  min-height:58px;
  padding:8px 9px!important;
  box-sizing:border-box;
  white-space:normal;
  overflow:hidden;
  text-align:center;
  font-size:13px;
}
.game-strip button img,
.game-strip button>span:first-child{
  flex:0 0 auto;
}
.game-strip .ge-open-button,
.game-strip .pet-wars-open-button{
  opacity:1!important;
  filter:none!important;
  color:#eee!important;
  background:#111!important;
  border-color:#376b51!important;
  cursor:pointer!important;
}
.game-strip .ge-open-button>span:last-child,
.game-strip .pet-wars-open-button>span:last-child{
  color:#eee!important;
  font-size:13px!important;
}
.game-strip .ge-open-button:hover,
.game-strip .pet-wars-open-button:hover{
  background:#14221a!important;
  border-color:#63d39a!important;
}
@media(max-width:1250px){
  .game-strip{grid-template-columns:minmax(190px,1.4fr) repeat(4,minmax(110px,1fr))}
}
@media(max-width:980px){
  .game-strip{grid-template-columns:repeat(3,minmax(0,1fr))}
  .game-strip>div{grid-column:1/-1;padding:3px 4px 7px}
}
@media(max-width:620px){
