:root{
  --adv-ink:#2b1b0f;
  --adv-deep:#17100b;
  --adv-stone:#30271f;
  --adv-stone-2:#211a14;
  --adv-wood:#5a351d;
  --adv-wood-dark:#2d180d;
  --adv-gold:#d7ad55;
  --adv-gold-light:#f2d88a;
  --adv-parchment:#d8c7a0;
  --adv-parchment-light:#eee0ba;
  --adv-parchment-dark:#a98d5e;
  --adv-red:#8e3023;
  --adv-green:#526c3f;
  --adv-blue:#415d73;
}
*{box-sizing:border-box}
html{background:#16100b}
body{
