/* Shooting Star AFK Mining */
.mining-open-button img{image-rendering:pixelated;object-fit:contain}.mining-dialog{width:min(920px,95vw);background:#17110d;border-color:#bb7b2a}.mining-heading{display:flex;align-items:center;gap:14px;border-bottom:2px solid #7e4b20;padding:0 0 12px;margin-bottom:12px}.mining-heading img{width:42px;height:42px;image-rendering:pixelated}.mining-heading h3{margin:0;color:#f2c56f}.mining-heading p{margin:4px 0 0;color:#c6ad86}.mining-locked{text-align:center;padding:55px 20px;border:2px solid #6b4928;background:linear-gradient(#21170f,#120d09)}.mining-lock-icon{font-size:52px}.mining-locked h4{color:#e9be69;font-size:21px;margin:10px}.mining-locked button{max-width:260px}.mining-hud{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:10px}.mining-hud span{background:#24170e;border:1px solid #825526;padding:9px;text-align:center;color:#b99a70}.mining-hud b{display:block;color:#f6d078;margin-top:3px}.star-arena{height:470px;position:relative;overflow:hidden;border:3px solid #70431f;background:linear-gradient(#242124 0 35%,#322d2a 36% 100%);isolation:isolate}.volcano-sky{position:absolute;inset:0;background:radial-gradient(circle at 80% 8%,#cf6040 0 2%,transparent 16%),linear-gradient(#302b31,#4a302b 45%,#211c1b 46%)}.volcano-sky i{position:absolute;width:5px;height:5px;border-radius:50%;background:#d9864e;box-shadow:0 0 8px #ff7438;animation:emberFloat 5s linear infinite}.volcano-sky i:nth-child(1){left:18%;top:54%;animation-delay:-1s}.volcano-sky i:nth-child(2){left:73%;top:45%;animation-delay:-3s}.volcano-sky i:nth-child(3){left:88%;top:70%;animation-delay:-2s}@keyframes emberFloat{to{transform:translateY(-220px);opacity:0}}.mountain{position:absolute;bottom:0;background:#1c191a;clip-path:polygon(0 100%,10% 42%,25% 56%,38% 8%,55% 49%,70% 20%,100% 100%)}.ridge-a{left:-5%;width:62%;height:270px}.ridge-b{right:-5%;width:55%;height:310px;background:#252022;transform:scaleX(-1)}.lava-pool{position:absolute;background:#ff9b19;border:5px solid #4e2414;box-shadow:0 0 18px #e34217 inset,0 0 16px #f35d1a;z-index:2;animation:lavaPulse 2.2s ease-in-out infinite}.lava-a{width:160px;height:38px;right:35px;bottom:42px;border-radius:50%}.lava-b{width:100px;height:26px;left:35px;bottom:90px;border-radius:50%;animation-delay:-1s}@keyframes lavaPulse{50%{filter:brightness(1.3)}}.shooting-star{position:absolute;z-index:5;left:50%;top:54%;width:260px;height:225px;transform:translate(-50%,-50%);filter:drop-shadow(0 18px 10px #090707)}.shooting-star>i,.star-core{position:absolute;background:linear-gradient(135deg,#3c6e67,#163f3d);border:3px solid #102b2a;clip-path:polygon(50% 0,62% 30%,100% 24%,74% 52%,96% 82%,60% 70%,46% 100%,36% 68%,0 78%,25% 50%,4% 20%,39% 31%)}.shooting-star>i:nth-child(1){inset:15px}.shooting-star>i:nth-child(2){width:130px;height:130px;left:5px;top:48px;transform:rotate(-25deg)}.shooting-star>i:nth-child(3){width:120px;height:145px;right:3px;top:35px;transform:rotate(33deg)}.shooting-star>i:nth-child(4){width:105px;height:110px;left:80px;top:0;transform:rotate(13deg)}.shooting-star>i:nth-child(5){width:110px;height:100px;left:70px;bottom:0;transform:rotate(-12deg)}.star-core{width:112px;height:112px;left:75px;top:56px;background:#285653}.shooting-star.struck{animation:starStrike .45s ease}@keyframes starStrike{20%{transform:translate(-50%,-50%) scale(.96) rotate(-2deg);filter:brightness(1.8)}60%{transform:translate(-50%,-50%) scale(1.03) rotate(2deg)}}.mining-pet{position:absolute;z-index:9;left:25%;bottom:70px;width:92px;height:110px;animation:petMinePosition 6s ease-in-out infinite}.mining-pet img{width:62px;height:62px;object-fit:contain;image-rendering:pixelated;position:absolute;bottom:0;left:10px;filter:drop-shadow(0 5px 2px #0008)}.mining-pet-label{position:absolute;top:0;left:50%;transform:translateX(-50%);white-space:nowrap;background:#152112;border:1px solid #d8c167;color:#f3dc76;padding:2px 5px;font-size:11px}.pet-pickaxe{position:absolute;font-size:40px;right:-2px;bottom:35px;transform-origin:10% 90%;animation:petPick 1.25s ease-in-out infinite}@keyframes petPick{0%,100%{transform:rotate(-45deg)}55%{transform:rotate(30deg)}}@keyframes petMinePosition{0%,100%{left:23%}50%{left:29%}}.fake-miner{position:absolute;z-index:7;width:65px;height:75px}.fake-miner img{width:45px;height:45px;object-fit:contain;image-rendering:pixelated;position:absolute;bottom:0}.fake-miner>span{position:absolute;right:0;bottom:23px;font-size:25px;animation:petPick 1.7s ease-in-out infinite}.fake-one{left:8%;bottom:40px}.fake-two{right:9%;bottom:85px}.fake-three{right:21%;bottom:28px}.fake-bubble{position:absolute;bottom:62px;left:50%;transform:translateX(-50%);width:180px;background:#eee2c1;color:#2b1b0d;border:2px solid #523919;border-radius:5px;padding:6px;font:12px Georgia,serif;text-align:center;opacity:0}.fake-bubble:after{content:"";position:absolute;left:45%;bottom:-9px;border:5px solid transparent;border-top-color:#eee2c1}.fake-bubble.pop{animation:bubbleTalk 8s ease both}@keyframes bubbleTalk{0%,100%{opacity:0;transform:translate(-50%,8px)}8%,80%{opacity:1;transform:translate(-50%,0)}}.mining-controls{display:grid;grid-template-columns:2fr 1fr;gap:10px;margin-top:10px}.mining-controls button{min-height:48px}.mining-game.is-active #mineStarButton:not(:disabled){animation:readyPulse 1.3s ease-in-out infinite}@keyframes readyPulse{50%{box-shadow:0 0 12px #e8b34c}}#miningMessage{text-align:center;color:#f1cf82;font-weight:bold}.mining-game>small{display:block;text-align:center;color:#a78d69}.star-dust i{position:absolute;z-index:6;width:7px;height:7px;background:#5f8f86;transform:rotate(45deg);animation:dustSpark 2s ease-out infinite}.star-dust i:nth-child(1){left:40%;top:50%}.star-dust i:nth-child(2){left:56%;top:44%;animation-delay:-.4s}.star-dust i:nth-child(3){left:49%;top:66%;animation-delay:-.8s}.star-dust i:nth-child(4){left:62%;top:58%;animation-delay:-1.2s}.star-dust i:nth-child(5){left:36%;top:61%;animation-delay:-1.6s}@keyframes dustSpark{to{transform:translate(25px,-3