@media(max-width:650px){.mining-hud{grid-template-columns:1fr}.star-arena{height:390px}.shooting-star{transform:translate(-50%,-50%) scale(.75)}.fake-bubble{width:120px;font-size:10px}.mining-controls{grid-template-columns:1fr}}

/* Seven-minute Shooting Star cycle and live miners */
.mining-cycle-rewards{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:10px;padding:10px 12px;border:2px solid #7b4d24;background:#21160e;color:#e8c985;font-size:12px}.mining-cycle-track{height:13px;border:2px solid #4e3018;background:#080604;overflow:hidden}.mining-cycle-track i{display:block;height:100%;width:0;background:linear-gradient(90deg,#8fd5ff,#d9f3ff);transition:width .5s linear}.shooting-star.degraded{filter:grayscale(.7) brightness(.58);transform:scale(.94)}.shooting-star.degraded:after{content:'DEGRADED';position:absolute;left:50%;top:50%;transform:translate(-50%,-50%) rotate(-8deg);padding:5px 9px;border:2px solid #3e281a;background:#110c08;color:#b59872;font-weight:900;letter-spacing:1px}.live-star-miners{position:absolute;inset:0;pointer-events:none;z-index:7}.live-star-miner{position:absolute;width:68px;height:70px;animation:liveMinerBob .85s steps(2) infinite}.live-star-miner img{position:absolute;width:34px;height:34px;object-fit:contain;image-rendering:pixelated;left:17px;top:25px}.live-star-miner>b{position:absolute;left:40px;top:22px;font-size:22px;transform-origin:20% 80%;animation:livePickaxe .8s ease-in-out infinite}.live-star-miner>span{position:absolute;left:50%;bottom:47px;transform:translateX(-50%);white-space:nowrap;padding:2px 4px;border:1px solid #93713b;background:rgba(10,7,4,.9);color:#ffe27a;font-size:9px;text-align:center}.live-star-miner small{display:block;color:#ddd;font-size:8px}.live-star-miner.miner-0{left:9%;top:51%}.live-star-miner.miner-1{left:22%;top:65%}.live-star-miner.miner-2{right:11%;top:52%}.live-star-miner.miner-3{right:25%;top:67%}.live-star-miner.miner-4{left:37%;top:74%}.live-star-miner.miner-5{right:38%;top:73%}@keyframes liveMinerBob{from{transform:translateY(0)}to{transform:translateY(3px)}}@keyframes livePickaxe{0%,100%{transform:rotate(-35deg)}50%{transform:rotate(28deg)}}
@media(max-width:700px){.mining-cycle-rewards{grid-template-columns:1fr}.live-star-miner:nth-child(n+5){display:none}}


/* Mining/Quest navigation buttons are always available; unauthenticated clicks open login. */
#openMining,#openQuests{opacity:1!important;filter:none!important;cursor:pointer!important;pointer-events:auto!important}
#openMining:disabled,#openQuests:disabled{opacity:1!important;filter:none!important;cursor:pointer!important;pointer-events:auto!important}


/* OSRS skill cap and always-active Mining / Quests menu buttons */
#openMining,#openQuests,
#openMining:disabled,#openQuests:disabled{
  opacity:1!important;
  filter:none!important;
  cursor:pointer!important;
  pointer-events:auto!important;
  color:#fff3c4!important;
  background:linear-gradient(#765025,#42260f)!important;
  border-color:#d5a64b!important;
  box-shadow:inset 0 0 0 2px #2a170b,0 2px 0 #1b0e07!important;
}
#openMining span,#openQuests span{color:#fff3c4!important}
#openMining:hover,#openQuests:hover{background:linear-gradient(#8a612c,#543116)!important;filter:brightness(1.08)!important}

/* Unified authentic pet presentation system */
.pet-visual{--pet-scale:1;--pet-facing:1;position:relative;display:inline-flex;align-items:flex-end;justify-content:center;width:100%;height:100%;transform:scaleX(var(--pet-facing));transform-origin:50% 85%;isolation:isolate}
.pet-visual img{position:relative;z-index:2;width:100%;height:100%;object-fit:contain;image-rendering:pixelated;transform:scale(var(--pet-scale));transform-origin:50% 88%;filter:drop-shadow(0 2px 1px rgba(0,0,0,.5))}
.pet-ground-shadow{position:absolute;z-index:1;left:17%;right:17%;bottom:4%;height:14%;border-radius:50%;background:rgba(0,0,0,.34);filter:blur(2px);transform:scaleX(calc(1 / var(--pet-facing)))}
.pet-visual[data-pet-ground="hover"] .pet-ground-shadow{opacity:.45;bottom:-7%;transform:scaleX(calc(1 / var(--pet-facing))) scale(.75)}
.pet-visual[data-pet-ground="hover"] img{animation:petAuthenticHover 2.1s ease-in-out infinite}
.pet-visual[data-pet-personality="tail"] img{animation:petAuthenticBreathe 1.8s ease-in-out infinite}
.pet-visual[data-pet-personality="heavy"] img{animation:petAuthenticHeavyIdle 2.4s steps(2,end) infinite}
.pet-visual[data-pet-personality="float"] img{animation:petAuthenticFloat 2.5s ease-in-out infinite}
.pet-visual[data-pet-personality="pulse"] img{animation:petAuthenticPulse 1.55s ease-in-out infinite}
.pet-visual[data-pet-personality="skitter"] img{animation:petAuthenticSkitterIdle .7s steps(2,end) infinite}
@keyframes petAuthenticBreathe{50%{transform:scale(calc(var(--pet-scale)*1.018)) translateY(-1px)}}
@keyframes petAuthenticHeavyIdle{50%{transform:scale(var(--pet-scale)) translateY(1px)}}
@keyframes petAuthenticHover{50%{transform:scale(var(--pet-scale)) translateY(-6px)}}
@keyframes petAuthenticFloat{50%{transform:scale(var(--pet-scale)) translateY(-4px) rotate(1deg)}}
@keyframes petAuthenticPulse{50%{transform:scale(calc(var(--pet-scale)*1.04));filter:brightness(1.12)}}
@keyframes petAuthenticSkitterIdle{50%{transform:scale(var(--pet-scale)) translateX(1px)}}

/* Natural roaming: sprite faces direction, name remains readable, feet move instead of spinning. */
.roaming-pet{position:fixed;left:0;top:0;z-index:45;width:88px;height:96px;pointer-events:none;transition-property:transform;transition-timing-function:linear;will-change:transform}
.roaming-pet .pet-sprite{position:absolute;left:12px;right:12px;bottom:0;height:66px}
.roaming-pet .pet-label{z-index:4;position:absolute;left:50%;bottom:72px;transform:translateX(-50%);min-width:max-content;white-space:nowrap;text-align:center;padding:2px 5px;background:rgba(16,11,6,.92);border:1px solid #9f793f;color:#ffe58c;font-size:10px;line-height:1.05}
.roaming-pet .pet-label small{display:block;color:#ddd;font-size:8px}
.roaming-pet.pet-is-walking .pet-visual[data-pet-ground="walk"] img{animation:petAuthenticWalk .34s steps(2,end) infinite}
.roaming-pet.pet-is-walking .pet-visual[data-pet-personality="heavy"] img{animation:petAuthenticHeavyWalk .48s steps(2,end) infinite}
.roaming-pet.pet-is-walking .pet-visual[data-pet-personality="skitter"] img{animation:petAuthenticSkitterWalk .18s steps(2,end) infinite}
.roaming-pet.pet-is-walking .pet-visual[data-pet-ground="hover"] img{animation:petAuthenticHoverMove .8s ease-in-out infinite}
.roaming-pet.pet-is-idle .pet-visual{animation:petLookAround 3.2s ease-in-out 1}
@keyframes petAuthenticWalk{0%{transform:scale(var(--pet-scale)) translateY(0) rotate(-1deg)}50%{transform:scale(var(--pet-scale)) translateY(-4px) rotate(1deg)}}
@keyframes petAuthenticHeavyWalk{0%{transform:scale(var(--pet-scale)) translateY(0)}50%{transform:scale(var(--pet-scale)) translateY(-3px)}}
@keyframes petAuthenticSkitterWalk{0%{transform:scale(var(--pet-scale)) translate(0,0)}50%{transform:scale(var(--pet-scale)) translate(2px,-2px)}}
@keyframes petAuthenticHoverMove{50%{transform:scale(var(--pet-scale)) translateY(-7px) rotate(2deg)}}
@keyframes petLookAround{35%{transform:scaleX(var(--pet-facing)) rotate(-2deg)}70%{transform:scaleX(calc(var(--pet-facing)*-1)) rotate(2deg)}100%{transform:scaleX(var(--pet-facing))}}

/* Bank and market use the same pet registry and proportions. */
.pet-bank-art{width:82px;height:72px;margin:0 auto 4px}
.pet-bank-mini{width:36px;height:32px;vertical-align:middle;margin-right:5px}
.pet-bank-slot>img{display:none!important}
.pet-bank-slot .pet-ground-shadow{bottom:1%}
.ge-item-icon .pet-visual{width:48px;height:48px}

/* Pet Wars: grounded, readable and more expressive without distorting the original sprites. */
.pet-war-visual{height:92px;width:130px;margin:0 auto;position:relative}
.pet-war-art{width:100%;height:100%}
.pet-wars-arena.running .fighter-left .pet-war-art{animation:petWarAuthenticLeft 1.05s ease-in-out infinite}
.pet-wars-arena.running .fighter-right .pet-war-art{animation:petWarAuthenticRight 1.05s ease-in-out infinite}
.pet-wars-arena.finished .winner .pet-war-art{animation:petWarAuthenticVictory .5s ease-in-out infinite alternate}
.pet-wars-arena.finished .loser .pet-war-art{transform:rotate(76deg) translateY(22px)}
@keyframes petWarAuthenticLeft{0%,100%{transform:translateX(0)}50%{transform:translateX(30px) translateY(-5px)}}
@keyframes petWarAuthenticRight{0%,100%{transform:translateX(0)}50%{transform:translateX(-30px) translateY(-5px)}}
@keyframes petWarAuthenticVictory{to{transform:translateY(-10px) rotate(4deg)}}

/* Shooting Star pets share the same true-to-sprite scaling and have varied mining rhythm. */
.mining-pet-visual{position:absolute;bottom:0;left:8px;width:68px;height:66px}
.mining-pet .star-pet-art,.live-star-miner .star-pet-art{width:100%;height:100%}
.mining-pet .star-pet-art img{animation:petMiningBody 1.25s ease-in-out infinite}
.live-star-miner .pet-visual{position:absolute;left:12px;top:22px;width:42px;height:42px}
