/* 2026-07-30 definitive pet-facing and cosmetic isolation fix.
   Only the pet artwork is mirrored. Cosmetics keep their original artwork
   orientation, labels remain readable, and every context uses the same markup. */
.pet-visual{
  --pet-facing:1!important;
  transform:none!important;
}
.pet-body-facing{
  position:relative;
  z-index:2;
  display:block;
  width:100%;
  height:100%;
  transform:scaleX(-1)!important;
  transform-origin:50% 85%;
}
.pet-body-facing>.pet-body{
  display:block;
  width:100%!important;
  height:100%!important;
  object-fit:contain!important;
  position:relative!important;
  z-index:2!important;
}
/* Never let idle or movement logic flip the complete pet/cosmetic stack. */
.roaming-pet.pet-is-idle .pet-visual{animation:none!important}
.roaming-pet .pet-visual{transform:none!important}
.roaming-pet .pet-body-facing{transform:scaleX(-1)!important}
/* Cosmetics are independent of the mirrored body. */
.pet-visual>.pet-cosmetic{transform-origin:50% 50%!important}
.pet-visual>.pet-odd-spectacles{
  left:var(--spec-x,50%)!important;
  top:var(--spec-y,36%)!important;
  width:var(--spec-w,52%)!important;
  height:auto!important;
  transform:translate(-50%,-50%) rotate(var(--spec-r,0deg))!important;
}
.pet-visual[data-pet-id="pet_free_cat"]>.pet-odd-spectacles{
  left:var(--spec-x,50%)!important;
  top:var(--spec-y,43%)!important;
  width:var(--spec-w,45%)!important;
}
