/* 2026-07-30 Shooting Star cosmetic fix.
   Mining movement must animate the pet body only. The old broad `img` rules
   also animated equipped hats, capes and spectacles, replacing their anchor
   transforms and throwing them away from the pet. */
.mining-pet .star-pet-art img,
.live-star-miner .star-pet-art img{
  animation:none!important;
}
.mining-pet .star-pet-art .pet-body-facing{
  animation:petMiningBodyFacing 1.25s ease-in-out infinite!important;
}
.live-star-miner .star-pet-art .pet-body-facing{
  animation:petMiningBodyFacing .92s ease-in-out infinite!important;
}
.live-star-miner:nth-child(2n) .star-pet-art .pet-body-facing{animation-delay:-.35s!important}
.live-star-miner:nth-child(3n) .star-pet-art .pet-body-facing{animation-delay:-.7s!important}
@keyframes petMiningBodyFacing{
  0%,100%{transform:scaleX(-1) scale(var(--pet-scale)) rotate(-1deg)}
  55%{transform:scaleX(-1) scale(var(--pet-scale)) translateY(2px) rotate(2deg)}
}
/* Keep every equipped cosmetic visible and anchored above the animated body. */
.mining-pet .star-pet-art>.pet-cosmetic,
.live-star-miner .star-pet-art>.pet-cosmetic{
  display:block!important;
  visibility:visible!important;
  opacity:1!important;
  z-index:20!important;
  animation:none!important;
}
.mining-pet .star-pet-art>.pet-fire-cape,
.live-star-miner .star-pet-art>.pet-fire-cape{
  z-index:1!important;
}
.mining-pet .star-pet-art>.pet-chefs-hat,
.mining-pet .star-pet-art>.pet-odd-spectacles,
.live-star-miner .star-pet-art>.pet-chefs-hat,
.live-star-miner .star-pet-art>.pet-odd-spectacles{
  z-index:21!important;
}

/* 2026-07-30 final Shooting Star cosmetic visibility safeguard. */
.mining-pet-visual .star-pet-art,
.live-star-miner .star-pet-art{position:relative!important;display:block!important;overflow:visible!important}
.mining-pet-visual .star-pet-art>.pet-cosmetic,
.live-star-miner .star-pet-art>.pet-cosmetic{display:block!important;visibility:visible!important;opacity:1!important}


