.toa-chat-prompt{position:absolute;left:50%;bottom:2.4%;z-index:24;transform:translateX(-50%);display:flex;align-items:center;gap:7px;padding:5px 9px;background:#100d08d9;border:1px solid #8d744b;color:#e7d19b;font:700 9px Arial,sans-serif;letter-spacing:.4px;box-shadow:0 3px 10px #0009}.toa-chat-prompt.hidden{display:none}.toa-chat-prompt kbd{min-width:19px;padding:2px 5px;border:1px solid #c9aa6b;background:#2b2418;color:#fff;text-align:center;font:900 10px Arial,sans-serif}
.toa-chat-form{position:absolute;left:50%;bottom:2.1%;z-index:40;transform:translateX(-50%);display:flex;width:min(420px,76%);padding:5px;background:#17130de8;border:2px solid #9b7e4c;box-shadow:0 5px 18px #000c}.toa-chat-form.hidden{display:none}.toa-chat-form input{flex:1;min-width:0;padding:8px 10px;background:#080704;border:1px solid #5d4e34;color:#fff6d4;font:700 12px Arial,sans-serif;outline:none}.toa-chat-form input:focus{border-color:#d4b66e}.toa-chat-form button{width:auto!important;margin:0 0 0 5px!important;padding:7px 12px!important;background:#4b3c22!important;border:1px solid #bc9854!important;color:#fff0bf!important;font-size:9px!important}
.toa-chat-bubble{position:absolute;left:50%;bottom:82%;z-index:35;transform:translateX(-50%);max-width:190px;padding:2px 4px;color:#fff100;text-align:center;white-space:normal;font:700 11px Arial,sans-serif;line-height:1.15;text-shadow:1px 1px 0 #000,-1px -1px 0 #000,1px -1px 0 #000,-1px 1px 0 #000;pointer-events:none}.toa-chat-bubble.hidden{display:none}.toa-remote-chat{left:58%;top:57%;bottom:auto;position:absolute}

/* Zebak 70% acid and 60%-40% tidal-wave mechanics */
.toa-crondis-room.toa-scream-cue{animation:toaArenaRumble .12s linear 10;box-shadow:inset 0 0 80px #d8f1ff66}
.toa-zebak-visual.screaming{opacity:1;background:radial-gradient(ellipse,#dff8ffbb 0 22%,#4aa0c777 42%,transparent 72%);animation:toaZebakScream 1.5s ease}
.toa-acid-shot{position:absolute;z-index:25;width:24px;height:24px;border-radius:50%;background:radial-gradient(circle,#eaff75 0 18%,#75c91d 43%,#253f08 70%);box-shadow:0 0 12px #9dff30;transform:translate(-50%,-50%);animation:toaAcidSpit .85s ease-in forwards}
.toa-acid-pool{position:absolute;z-index:11;border-radius:46% 54% 42% 58%/58% 38% 62% 42%;background:radial-gradient(ellipse,#b9f248cc 0 16%,#5d9a20dd 45%,#243b10e8 76%);border:2px solid #a7dd43;box-shadow:inset 0 0 14px #dfff6d99,0 0 10px #75b82d99;transform:scale(0);animation:toaAcidLand .55s var(--acid-delay) ease-out forwards,toaAcidBubble 1.1s calc(var(--acid-delay) + .55s) ease-in-out infinite alternate}
.toa-tidal-wave{position:absolute;top:0;left:-10%;z-index:24;width:16%;height:100%;pointer-events:none;filter:drop-shadow(5px 0 8px #052f4dcc) drop-shadow(0 0 9px #68cbe1aa)}
.toa-tidal-wave::before{content:"";position:absolute;z-index:4;top:0;right:-18%;width:42%;height:100%;background:linear-gradient(90deg,#d8fbffb8,transparent);filter:blur(5px);opacity:.72;animation:toaWaveMist .28s ease-in-out infinite alternate}
.toa-wave-water{position:absolute;left:0;width:100%;display:block;overflow:hidden;background:linear-gradient(90deg,#082d47f2 0%,#0c5078f2 28%,#168bb1ec 61%,#70d4e4dc 86%,#d9fbfff2 100%);border-right:3px solid #ecffff;box-shadow:inset -13px 0 12px #9feef188,inset 6px 0 10px #041c2eaa;clip-path:polygon(0 0,82% 0,100% 3%,86% 7%,100% 11%,84% 16%,100% 21%,87% 27%,100% 32%,85% 38%,100% 44%,86% 50%,100% 56%,84% 62%,100% 68%,86% 74%,100% 80%,84% 86%,100% 92%,86% 96%,100% 100%,0 100%)}
.toa-wave-water::before{content:"";position:absolute;z-index:2;top:0;right:0;width:34%;height:100%;background:radial-gradient(ellipse at right,#fff 0 8%,#c8f8ffcc 10% 22%,transparent 25%) 0 0/100% 29px repeat-y;animation:toaWaveFoam .22s linear infinite}
.toa-wave-water::after{content:"";position:absolute;inset:-18px -10px;background:repeating-linear-gradient(165deg,transparent 0 11px,#b9f5ff25 12px 15px,transparent 16px 25px),radial-gradient(ellipse at 65% 50%,#d5fbff42 0 8%,transparent 10%);background-size:auto,80px 42px;animation:toaWaterFlow .3s linear infinite}
.toa-wave-water.top{top:0;border-bottom:2px solid #8dd7df}.toa-wave-water.bottom{bottom:0;border-top:2px solid #8dd7df}
@keyframes toaZebakScream{0%{transform:translate(-50%,-50%) scale(1)}20%{transform:translate(-50%,-54%) scale(1.18)}35%,55%,75%{filter:drop-shadow(0 0 32px #bff3ff);transform:translate(-52%,-54%) scale(1.22)}45%,65%,85%{transform:translate(-48%,-54%) scale(1.22)}100%{opacity:0;transform:translate(-50%,-50%) scale(1)}}
@keyframes toaArenaRumble{25%{transform:translateX(-2px)}75%{transform:translateX(2px)}}
@keyframes toaAcidSpit{0%{left:50%;top:17%;transform:translate(-50%,-50%) scale(.4)}100%{left:50%;top:62%;transform:translate(-50%,-50%) scale(1.45);opacity:0}}
@keyframes toaAcidLand{to{transform:scale(1)}}
@keyframes toaAcidBubble{to{filter:brightness(1.22);transform:scale(1.025)}}
@keyframes toaWaterFlow{to{transform:translate(13px,17px)}}
@keyframes toaWaveFoam{to{background-position:0 29px}}
@keyframes toaWaveMist{to{opacity:.42;transform:scaleX(1.18)}}

/* Zebak 40%-0% blood-orb enrage and completion spirit */
.toa-blood-orb{position:absolute;z-index:23;width:30px;height:30px;border-radius:50%;transform:translate(-50%,-50%);background:radial-gradient(circle at 36% 32%,#fff 0 5%,#ff9aa5 8%,#d1192f 34%,#650413 68%,#210006 100%);border:2px solid #ff6475;box-shadow:0 0 10px #ff3048,0 0 22px #a5001c,inset 0 0 8px #ffb2bb;animation:toaBloodPulse .68s ease-in-out infinite alternate;pointer-events:none}
.toa-blood-orb::after{content:"";position:absolute;inset:-7px;border:2px solid #ff3b5088;border-radius:50%;animation:toaBloodRing 1s ease-out infinite}
@keyframes toaBloodPulse{to{transform:translate(-50%,-50%) scale(1.14);filter:brightness(1.22)}}
@keyframes toaBloodRing{to{transform:scale(1.35);opacity:0}}
.toa-helpful-spirit{position:absolute;z-index:32;width:78px;height:88px;transform:translate(-50%,-50%);border:0!important;background:transparent!important;padding:0!important;margin:0!important;cursor:pointer;filter:drop-shadow(0 0 10px #bff6ff)}
.toa-helpful-spirit i{position:absolute;left:50%;top:38%;width:34px;height:48px;transform:translate(-50%,-50%);border-radius:48% 48% 42% 42%;background:radial-gradient(circle at 50% 25%,#fff 0 12%,#b7f4ff 17% 34%,#65c9dfaa 53%,transparent 72%);box-shadow:0 0 18px #b8f7ff;animation:toaSpiritFloat 1.3s ease-in-out infinite alternate}
.toa-helpful-spirit i::after{content:"";position:absolute;left:50%;bottom:-14px;width:42px;height:24px;transform:translateX(-50%);background:linear-gradient(135deg,transparent 20%,#7fd7e6aa 22% 45%,transparent 47%),linear-gradient(45deg,transparent 20%,#7fd7e6aa 22% 45%,transparent 47%);filter:blur(1px)}
.toa-helpful-spirit b{position:absolute;left:50%;bottom:0;transform:translateX(-50%);white-space:nowrap;color:#fff38a;font:800 10px Arial,sans-serif;text-shadow:1px 1px #000,-1px -1px #000,0 0 5px #000}
@keyframes toaSpiritFloat{to{transform:translate(-50%,-58%);filter:brightness(1.18)}}
.toa-zebak-hud.toa-defeated .toa-zebak-hp-track{filter:grayscale(1);opacity:.72}

/* Zebak final 10% rage */
.toa-helpful-spirit{-webkit-appearance:none;appearance:none;outline:none!important;box-shadow:none!important;overflow:visible;border-radius:0!important}
.toa-helpful-spirit:focus,.toa-helpful-spirit:focus-visible,.toa-helpful-spirit:hover{outline:none!important;box-shadow:none!important;background:transparent!important}
.toa-final-shake{animation:toaFinalArenaShake .18s linear infinite}
@keyframes toaFinalArenaShake{0%,100%{transform:translate(0,0)}25%{transform:translate(-1px,1px)}50%{transform:translate(1px,0)}75%{transform:translate(0,-1px)}}
.toa-boulder-warning{position:absolute;z-index:27;width:58px;height:30px;transform:translate(-50%,-50%);border-radius:50%;border:3px solid #ff5a35;background:radial-gradient(ellipse,#ffb13b55 0 38%,#e42d1966 42% 56%,transparent 61%);box-shadow:0 0 12px #ff3b22,inset 0 0 9px #ffb33b;animation:toaBoulderWarn .38s ease-in-out infinite alternate;pointer-events:none}
@keyframes toaBoulderWarn{from{scale:.88;opacity:.68}to{scale:1.08;opacity:1}}
.toa-falling-boulder{position:absolute;z-index:29;width:48px;height:48px;transform:translate(-50%,-170%) scale(1.25) rotate(-20deg);border-radius:46% 54% 43% 57%;background:radial-gradient(circle at 32% 27%,#9b8d75 0 10%,#675b49 28%,#332b22 67%,#17120e 100%);box-shadow:inset -5px -7px 7px #120d09,0 16px 8px #0008;animation:toaBoulderFall .52s cubic-bezier(.45,.02,.8,.48) forwards;pointer-events:none}
.toa-falling-boulder::before,.toa-falling-boulder::after{content:"";position:absolute;background:#211a14;border-radius:50%;opacity:.7}.toa-falling-boulder::before{width:13px;height:8px;left:8px;top:13px;rotate:-25deg}.toa-falling-boulder::after{width:10px;height:13px;right:8px;bottom:9px;rotate:35deg}
@keyframes toaBoulderFall{to{transform:translate(-50%,-50%) scale(1) rotate(16deg)}}
.toa-falling-boulder.landed{animation:toaBoulderLand .5s ease-out forwards}
@keyframes toaBoulderLand{0%{filter:brightness(1.7);scale:1.12}100%{filter:brightness(.7);scale:.82;opacity:0}}

/* ToA defeat / co-op spectator panel */
.toa-defeated-panel{position:absolute;left:50%;top:52%;z-index:80;width:min(440px,86%);transform:translate(-50%,-50%);padding:22px 20px;text-align:center;background:linear-gradient(#17130feF,#090806f5);border:3px solid #8d6a39;box-shadow:0 0 0 3px #241507,0 18px 60px #000;color:#ead9ad}
.toa-defeated-panel.hidden{display:none}.toa-defeated-panel>span{font:900 10px Arial,sans-serif;letter-spacing:2px;color:#bd9759}.toa-defeated-panel h4{margin:8px 0;color:#d64c3d;font:900 24px Georgia,serif;text-shadow:2px 2px #000}.toa-defeated-panel p{margin:0 0 16px;color:#ddd0ad;font:700 12px Arial,sans-serif}.toa-defeated-actions{display:flex;gap:10px;justify-content:center;flex-wrap:wrap}.toa-defeated-actions button{width:auto!important;margin:0!important;padding:9px 13px!important}.toa-defeated-actions button:last-child{background:#5b201c!important;border-color:#bb5a4b!important}.toa-player-sprite.toa-dead{display:none!important}

.toa-party-bar.raid-started{display:none!important}
.toa-path-label.complete{border-color:#4fdb62;color:#dfffe3;background:#07150bdc;box-shadow:0 0 16px #35cf5577,inset 0 0 10px #1d7d3344}
.toa-path-label.complete span{color:#68ed78}
/* Keep overhead chat readable when the character sprite faces left. */
.toa-player-sprite.facing-left > .toa-chat-bubble{transform:translateX(-50%) scaleX(-1)}
/* Network teammate positions are interpolated in JS; avoid visual snapping. */
.toa-crondis-teammate{will-change:left,top;transition:left .06s linear,top .06s linear,filter .15s}

/* Path of Scarabas */
.toa-context-scarabas{left:auto;right:18%;}
.toa-scarabas-room{position:absolute;inset:0;z-index:31;background:#17120c url('assets/toa-scarabas-room.png') center/100% 100% no-repeat;overflow:hidden}
.toa-scarabas-room.hidden{display:none}
.toa-scarabas-vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 55%,transparent 40%,rgba(0,0,0,.42));z-index:1}
.toa-scarabas-player{left:47%;top:88%;z-index:8}
.toa-scarabas-teammate{left:53%;top:88%;z-index:8;filter:hue-rotate(90deg) drop-shadow(0 3px 2px #000b)}
.toa-arena-banner{position:absolute;z-index:20;left:50%;top:8%;transform:translateX(-50%);padding:9px 18px;background:#090807df;border:2px solid #c8a65f;box-shadow:0 0 18px #000;color:#ead59a;text-align:center;letter-spacing:1px;pointer-events:none}
.toa-arena-banner span{display:block;font-size:9px}.toa-arena-banner b{font-size:17px;color:#fff1bd}
.toa-path-label.toa-scarabas.unlocked{border-color:#8ec66f;color:#d9ffc5;box-shadow:0 0 13px #69a34d99}.toa-path-label.toa-scarabas.unlocked span{color:#9ee684}

/* CatAsthma TOA testing controls */
.signed-in-controls{display:flex;align-items:center;justify-content:flex-end;gap:8px}
.admin-button{align-self:stretch;padding:9px 12px;border:1px solid #c89432;background:linear-gradient(#3a2a0d,#171006);color:#ffd66c;font-weight:900;letter-spacing:1px;cursor:pointer;box-shadow:inset 0 0 0 1px #6f501b}
.admin-button:hover{filter:brightness(1.18)}
.admin-button.active{border-color:#ff6868;background:linear-gradient(#681414,#240606);color:#fff0f0;box-shadow:0 0 7px #ff2222,0 0 18px #ff1717cc,0 0 32px #ff000066,inset 0 0 0 1px #a83838;animation:adminRedPulse 1.15s ease-in-out infinite}
@keyframes adminRedPulse{0%,100%{filter:brightness(1);box-shadow:0 0 7px #ff2222,0 0 18px #ff1717cc,0 0 32px #ff000066,inset 0 0 0 1px #a83838}50%{filter:brightness(1.24);box-shadow:0 0 10px #ff5555,0 0 25px #ff2020,0 0 42px #ff000099,inset 0 0 0 1px #e45d5d}}
@media(max-width:760px){.signed-in-controls{align-items:stretch}.admin-button{padding:8px}}

/* Kephri phase 1 */
.toa-kephri-hud{position:absolute;z-index:18;left:50%;top:2.2%;transform:translateX(-50%);width:min(430px,52%);pointer-events:none;text-align:center;font-family:Georgia,serif;text-shadow:2px 2px #000}
.toa-kephri-hud.hidden{display:none}.toa-kephri-name{display:flex;justify-content:space-between;color:#f4d888;font-size:13px;font-weight:900;letter-spacing:1.5px}.toa-kephri-name b{color:#fff3c4}.toa-kephri-hp{height:12px;margin-top:4px;background:#160b08;border:2px solid #bc8a34;box-shadow:0 0 0 2px #000,0 0 12px #d36b1b88;overflow:hidden}.toa-kephri-hp i{display:block;width:100%;height:100%;background:linear-gradient(#e7432f,#971913);transition:width .15s linear}.toa-kephri-phase{margin-top:5px;color:#e8c995;font-size:9px;letter-spacing:1px}
.toa-scarabas-effects{position:absolute;inset:0;z-index:7;pointer-events:none;overflow:hidden}
.toa-scarabas-player.toa-keris-armed::after,.toa-scarabas-teammate.toa-keris-armed::after{content:"";position:absolute;width:34px;height:34px;left:5px;top:-16px;background:url('assets/keris-partisan.png') center/contain no-repeat;transform:scaleX(-1) rotate(40deg);transform-origin:20% 80%;filter:drop-shadow(1px 2px 1px #000);z-index:-1}
.toa-player-sprite.facing-left.toa-keris-armed::after{transform:rotate(40deg)}
.toa-scarabas-player.toa-keris-strike::after,.toa-scarabas-teammate.toa-keris-strike::after{animation:toaKerisStrike .32s ease-out}@keyframes toaKerisStrike{0%{rotate:0deg}45%{rotate:-55deg}100%{rotate:0deg}}
.toa-kephri-hit{position:absolute;width:7px;height:7px;border-radius:50%;background:#ffe275;box-shadow:0 0 7px 3px #ff6d00;transform:translate(-50%,-50%);animation:toaKephriHit .45s ease-out forwards}@keyframes toaKephriHit{to{transform:translate(-50%,-50%) scale(3);opacity:0}}
.toa-fireball-shadow{position:absolute;width:7.5%;aspect-ratio:1;border-radius:50%;transform:translate(-50%,-50%);background:radial-gradient(circle,#160000aa 0 38%,#5b130bbb 43%,#ff5a2233 62%,transparent 70%);box-shadow:0 0 14px #e43b1d88;animation:toaShadowPulse .45s infinite alternate;z-index:2}@keyframes toaShadowPulse{to{scale:1.18;filter:brightness(1.35)}}
.toa-kephri-fireball{position:absolute;width:5.4%;aspect-ratio:1;border-radius:50%;transform:translate(-50%,-50%);background:radial-gradient(circle at 35% 30%,#fff7b3 0 12%,#ff9b26 28%,#da2e13 58%,#530900 75%,transparent 77%);box-shadow:0 0 16px 6px #ff4d16;z-index:4}
.toa-fireball-impact{position:absolute;width:11%;aspect-ratio:1;border-radius:50%;transform:translate(-50%,-50%);background:radial-gradient(circle,#fff3a8,#ff781f 28%,#c91f0e 49%,transparent 70%);animation:toaFireImpact .55s ease-out forwards;z-index:5}@keyframes toaFireImpact{to{scale:2.1;opacity:0}}
.toa-kephri-damage{position:absolute;transform:translate(-50%,-50%);color:white;background:#b0201b;border:2px solid #fff;border-radius:50%;min-width:22px;height:22px;display:grid;place-items:center;font:900 12px Arial;box-shadow:0 2px 3px #000;animation:toaKDamage .9s ease-out forwards;z-index:9}@keyframes toaKDamage{to{translate:0 -28px;opacity:0}}
.toa-scarabas-room.kephri-active .toa-scarabas-vignette{background:radial-gradient(ellipse at 50% 55%,transparent 52%,rgba(0,0,0,.34))}

.toa-scarabas-room .toa-player-hud{left:1.5%;top:9%;bottom:auto;}
.toa-scarabas-room.kephri-shake{animation:toaKephriShake .09s linear 10}@keyframes toaKephriShake{25%{translate:-5px 2px}50%{translate:4px -3px}75%{translate:-2px -2px}}
.toa-dung-ball{position:absolute;width:4.3%;aspect-ratio:1;border-radius:48% 52% 45% 55%;transform:translate(-50%,-50%);z-index:5;background:radial-gradient(circle at 34% 28%,#a8783e 0 12%,#68431f 38%,#35200f 72%);box-shadow:0 3px 4px #000b,0 0 0 2px #211307}.toa-dung-ball:not(.flying){animation:toaDungPulse .75s infinite alternate}@keyframes toaDungPulse{to{filter:brightness(1.25);scale:1.06}}
.toa-dung-explosion{position:absolute;width:11%;aspect-ratio:1;border-radius:50%;transform:translate(-50%,-50%);z-index:7;background:radial-gradient(circle,#d7b35b 0 8%,#75441e 28%,#3b2613 50%,transparent 71%);animation:toaDungBurst .65s ease-out forwards}@keyframes toaDungBurst{to{scale:2.2;opacity:0}}
.toa-kephri-flea{position:absolute;width:.9%;aspect-ratio:1;border-radius:55% 45% 55% 45%;transform:translate(-50%,-50%) rotate(35deg);z-index:5;background:#5a2417;box-shadow:-3px 0 0 -1px #26100b,3px 0 0 -1px #26100b,0 0 4px #ff8b3c;animation:toaFleaScuttle .18s steps(2) infinite}@keyframes toaFleaScuttle{to{rotate:55deg;scale:1.12}}
.toa-flea-shot{position:absolute;width:1.1%;aspect-ratio:1;border-radius:50%;transform:translate(-50%,-50%);z-index:8;background:#87d13e;box-shadow:0 0 5px 2px #b8ff61}
.toa-kephri-damage.blocked{background:#294b22;color:#fff}

/* Kephri flea refinement: tiny airborne swarm with subtle fluttering. */
.toa-kephri-flea{min-width:5px;max-width:9px;filter:drop-shadow(0 1px 1px #000);animation:toaFleaScuttle .14s steps(2) infinite,toaFleaHover .7s ease-in-out infinite alternate}
@keyframes toaFleaHover{to{margin-top:-3px;filter:brightness(1.18) drop-shadow(0 3px 2px #0008)}}

/* Kephri Dung Strike */
.toa-dung-strike-flies{position:absolute;width:7%;aspect-ratio:1;transform:translate(-50%,-55%);z-index:12;pointer-events:none;animation:toaDungSwarmPulse .35s ease-in-out infinite alternate}
.toa-dung-strike-flies b{position:absolute;left:50%;top:50%;width:4px;height:3px;border-radius:50%;background:#25140b;box-shadow:0 0 3px #d19a45;animation:toaDungFly 1s linear infinite;animation-delay:calc(var(--fly-i)*-.11s)}
@keyframes toaDungFly{0%{transform:rotate(calc(var(--fly-i)*40deg)) translateX(8px) rotate(0)}50%{transform:rotate(calc(var(--fly-i)*40deg + 150deg)) translateX(18px) rotate(-150deg)}100%{transform:rotate(calc(var(--fly-i)*40deg + 360deg)) translateX(8px) rotate(-360deg)}}
@keyframes toaDungSwarmPulse{to{scale:1.15;filter:brightness(1.3)}}
.toa-dung-wall-ball{position:absolute;width:4.2%;aspect-ratio:1;border-radius:48% 52% 45% 55%;transform:translate(-50%,-50%) scale(0);z-index:7;background:radial-gradient(circle at 32% 25%,#b17a38 0 10%,#70451f 35%,#38200e 72%);box-shadow:0 3px 5px #000c,0 0 0 2px #241408;animation:toaDungWallLand .32s cubic-bezier(.2,1.5,.5,1) forwards,toaDungWallBuzz 1.2s .35s infinite alternate;animation-delay:calc(var(--dung-i)*.045s)}
@keyframes toaDungWallLand{to{transform:translate(-50%,-50%) scale(1)}}
@keyframes toaDungWallBuzz{to{filter:brightness(1.16);rotate:5deg}}
.toa-dung-knock{transition:left .38s cubic-bezier(.15,.75,.25,1),top .38s cubic-bezier(.15,.75,.25,1)!important;filter:drop-shadow(0 0 5px #8d5b26)}

/* Kephri 50% scarab reinforcement phase */
.toa-kephri-add{position:absolute;width:8.5%;aspect-ratio:1;transform:translate(-50%,-50%);z-index:8;background:url('assets/kephri-scarab.png') center/contain no-repeat;filter:drop-shadow(0 4px 3px #000b);transition:left .08s linear,top .08s linear;pointer-events:none}
.toa-kephri-add.blue{filter:hue-rotate(155deg) saturate(1.6) brightness(1.15) drop-shadow(0 0 8px #42cfff)}
.toa-kephri-add.hit{animation:toaAddHit .18s linear}.toa-kephri-add.attack{animation:toaAddAttack .32s ease-out}.toa-kephri-add.burst{animation:toaAddBurst .4s ease-out forwards}
@keyframes toaAddHit{50%{filter:brightness(2) drop-shadow(0 0 9px #fff)}}
