  0%{opacity:0;transform:translate(0,0) rotate(0) scale(calc(var(--lost-size)*.6))}
  9%{opacity:1}
  52%{opacity:1;transform:translate(calc(var(--lost-x)*.62),var(--lost-y)) rotate(calc(var(--lost-r)*.55)) scale(var(--lost-size))}
  100%{opacity:0;transform:translate(var(--lost-x),calc(var(--lost-y) + 118px)) rotate(var(--lost-r)) scale(calc(var(--lost-size)*.68))}
}
