  position:relative!important;border:3px ridge #ad833f!important;outline:2px solid #1a1007!important;border-radius:4px!important;
  background:linear-gradient(180deg,#302313 0%,#151008 44%,#090705 100%)!important;
  box-shadow:0 14px 34px #000d,inset 0 0 0 2px #5f4422,inset 0 0 32px #000c!important;
  padding:11px 9px 9px!important;gap:7px!important;
}
.qm-broadcast-sidebar .qm-career-panel:before{content:"⚜";display:grid;place-items:center;width:34px;height:34px;margin:-2px auto 5px;border-radius:50%;border:2px solid #d0a04a;background:#241609;color:#f0c96d;font-size:18px;box-shadow:0 3px 0 #000,inset 0 0 10px #0008}
.qm-broadcast-sidebar .qm-career-panel header{padding:0 4px 9px!important;border-bottom:2px solid #9b7132!important}
.qm-broadcast-sidebar .qm-career-panel header span{color:#c7933f!important;letter-spacing:2.5px!important}
.qm-broadcast-sidebar .qm-career-panel header b{font-size:16px!important;color:#ffe18f!important;text-shadow:0 2px #000!important}
.qm-broadcast-sidebar .qm-career-panel section{position:relative!important;padding:7px 6px!important;border:2px ridge #6f5128!important;background:linear-gradient(180deg,#2a1d10,#100b07)!important;box-shadow:inset 0 0 14px #000a!important}
.qm-broadcast-sidebar .qm-career-panel h3{margin:-1px -1px 6px!important;padding:5px!important;background:#161009!important;border-bottom:1px solid #8a632d!important;color:#f2cb70!important;font-size:9px!important;letter-spacing:1.2px!important}
.qm-career-row{grid-template-columns:22px minmax(0,1fr) auto!important;min-height:25px!important;border-bottom:1px dotted #644923!important}
.qm-career-rank{display:grid;place-items:center;width:18px;height:18px;border-radius:50%;background:#2e1d0c;border:1px solid #ba8736;color:#ffd777!important}
.qm-career-name{color:#f3dfaf!important}.qm-career-name small{color:#a38c68!important}.qm-career-value{color:#ffd36d!important}
.qm-career-panel footer{padding-top:2px!important;color:#8c7755!important}

.qm-prediction>div{grid-template-columns:1fr 1fr!important}
.qm-prediction-split span[data-prediction="draw"],.qm-prediction-split .is-draw{display:none!important}
@media(max-width:1150px){.quidditch-mode-layout{grid-template-columns:20vw minmax(0,1fr) 21vw!important}.quidditch-mode-layout>.qm-commentator-sidebar{grid-template-rows:minmax(220px,34vh) 180px!important}.qm-commentator-sidebar .qm-commentary{height:180px!important}}
