/* Commentator tips and larger live commentary panel */
.quidditch-mode-layout>.qm-commentator-sidebar{
  grid-template-rows:minmax(255px,36vh) 38px 258px!important;
  gap:7px!important;
}
.qm-commentator-sidebar .qm-commentary{
  height:258px!important;
  min-height:258px!important;
  padding:41px 31px 29px!important;
}
.qm-commentator-sidebar .qm-commentary-title{left:31px!important;right:31px!important;top:21px!important}
.qm-commentator-sidebar .qm-commentary-log{gap:6px!important}
.qm-commentator-sidebar .qm-commentary-line{font-size:9px!important;line-height:1.28!important;grid-template-columns:29px minmax(0,1fr)!important}
.qm-throw-coin{
  width:100%!important;height:38px!important;min-height:38px!important;margin:0!important;padding:3px 12px!important;
  display:flex!important;align-items:center!important;justify-content:center!important;gap:9px!important;
  border:2px ridge #ad833f!important;outline:1px solid #1b1007!important;border-radius:2px!important;
  background:linear-gradient(180deg,#563719 0%,#2b190c 52%,#171006 100%)!important;
  color:#ffe49b!important;box-shadow:0 5px 10px #0009,inset 0 0 0 1px #765027!important;
  cursor:pointer!important;transition:filter .12s ease,transform .12s ease!important;
}
.qm-throw-coin:hover:not(:disabled){filter:brightness(1.18)!important;transform:translateY(-1px)!important}
.qm-throw-coin:active:not(:disabled){transform:translateY(1px)!important}
.qm-throw-coin:disabled{opacity:.48!important;cursor:not-allowed!important;filter:grayscale(.4)!important}
.qm-throw-coin img{width:18px!important;height:14px!important;object-fit:contain!important;image-rendering:pixelated!important;filter:drop-shadow(1px 2px 0 #000)!important}
.qm-throw-coin span{display:flex;align-items:center}.qm-throw-coin b{font:900 10px/1 Georgia,serif;letter-spacing:1.5px}.qm-throw-coin.is-used{opacity:.55!important;filter:grayscale(.45)!important}.qm-throw-coin.is-used b{letter-spacing:.8px;font-size:8px}
.qm-commentator-studio.is-tipped{animation:qmTipStudioGlow .45s ease-in-out 3 alternate}
.qm-commentator-studio.is-tipped:before{content:"+200 GP";position:absolute;z-index:8;left:50%;top:17%;transform:translateX(-50%);padding:5px 9px;border:2px ridge #e4bd57;background:#211406;color:#ffe99a;font:900 11px/1 monospace;letter-spacing:1px;animation:qmTipFloat 2.1s ease-out forwards;white-space:nowrap;box-shadow:0 4px 10px #000b}
@keyframes qmTipStudioGlow{from{box-shadow:0 12px 26px #0009,inset 0 0 0 2px #3d2b18}to{box-shadow:0 12px 28px #0009,0 0 18px #ffd45d88,inset 0 0 18px #ffc94a55}}
@keyframes qmTipFloat{0%{opacity:0;transform:translate(-50%,12px)}15%{opacity:1}80%{opacity:1}100%{opacity:0;transform:translate(-50%,-25px)}}
