/* Barry Bramble community tip milestone */
.qm-commentator-toprow{
  display:grid;grid-template-columns:minmax(0,1fr) 72px;gap:6px;align-items:stretch;min-width:0;
}
.qm-commentator-toprow .qm-commentator-studio{width:100%;height:auto!important;aspect-ratio:1/1;min-width:0}
.qm-tip-goal{
  position:relative;display:grid;grid-template-rows:auto minmax(110px,1fr) auto auto;gap:5px;
  min-width:0;padding:7px 5px 6px;box-sizing:border-box;overflow:hidden;
  background:linear-gradient(180deg,#21160d,#0d0906);border:2px ridge #a77337;
  box-shadow:inset 0 0 0 1px #4f3419,0 6px 15px #0009;color:#efd17f;text-align:center;font-family:Georgia,serif;
}
.qm-tip-goal header{display:grid;gap:2px;padding-bottom:5px;border-bottom:1px solid #6f4c24}
.qm-tip-goal header b{font:900 7px/1 Georgia,serif;letter-spacing:.8px;color:#f3d68f}
.qm-tip-goal header span{font:900 14px/1 Georgia,serif;color:#ffd75e;text-shadow:0 2px #000}
.qm-tip-goal-track{
  position:relative;align-self:stretch;min-height:120px;overflow:hidden;border:2px inset #765427;
  background:linear-gradient(90deg,#080603,#1a1007 50%,#080603);box-shadow:inset 0 0 14px #000;
}
.qm-tip-goal-fill{
  position:absolute;left:0;right:0;bottom:0;height:0%;transition:height 1.4s cubic-bezier(.22,.8,.24,1);
  background:linear-gradient(180deg,#f7d75b,#b87812 45%,#754407);opacity:.3;
  box-shadow:0 -4px 12px #f6cb4d66;
}
.qm-tip-goal-coins{position:absolute;inset:0;overflow:hidden;pointer-events:none}
.qm-tip-goal-coins i{
  position:absolute;width:18px;height:13px;background:url('assets/commentator-coin.png') center/contain no-repeat;
  transform:rotate(var(--coin-r,0deg));filter:drop-shadow(1px 2px 0 #000);animation:qmTipCoinShimmer 2.8s ease-in-out infinite alternate;
}
@keyframes qmTipCoinShimmer{from{filter:drop-shadow(1px 2px 0 #000) brightness(.9)}to{filter:drop-shadow(1px 2px 0 #000) brightness(1.3)}}
.qm-tip-goal-track strong{
  position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);z-index:3;padding:4px 3px;
  background:#100b07d9;border:1px solid #7d5929;color:#fff0a9;font:900 10px/1 Georgia,serif;text-shadow:0 1px #000;
}
.qm-tip-goal>img{width:54px;max-width:100%;height:35px;object-fit:contain;margin:auto;image-rendering:pixelated;filter:drop-shadow(1px 2px 0 #000)}
.qm-tip-goal>small{display:block;min-height:20px;color:#bca474;font:700 6px/1.15 monospace;overflow-wrap:anywhere}
.qm-tip-goal.is-unlocked{border-color:#e8c557;box-shadow:0 0 18px #e8c55766,inset 0 0 0 1px #76551f}
.qm-tip-goal.is-unlocked .qm-tip-goal-track strong{color:#fff7b4;border-color:#dfbd4f}
.qm-tip-goal.is-unlocked>img{animation:qmBoaterUnlocked 1.4s ease-in-out infinite alternate}
@keyframes qmBoaterUnlocked{from{transform:translateY(0) rotate(-1deg)}to{transform:translateY(-3px) rotate(1deg)}}
.pet-barrys-boater{z-index:8!important;filter:drop-shadow(1px 2px 1px #0009)}
