/* Rooftop Rumble — Skipper achievement and animated pet */
.achievement-group h4 .achievement-game-skill{margin-left:auto;font:800 9px/1 monospace;letter-spacing:1px;color:#9bd5ad;border:1px solid #55785d;padding:4px 6px;background:#172019}
.achievement-locked-future{opacity:.92;border-color:#8f7544;background:linear-gradient(90deg,#241b14,#2d281b)}
.achievement-locked-future .achievement-status{color:#e4c778;border-color:#9d7b3d;background:#19130d}
.skipper-achievement-preview{position:relative;display:block;overflow:hidden;padding:0!important;background:#0d0b09!important}
.skipper-achievement-preview img{display:block;width:100%;height:100%;object-fit:cover;object-position:center 24%;image-rendering:auto}
.pet-visual[data-pet-id="pet_skipper"]{--pet-scale:.94}
.pet-visual[data-pet-id="pet_skipper"] .skipper-body{position:relative;display:block;width:100%;height:100%}
.pet-visual[data-pet-id="pet_skipper"] .skipper-frame{position:absolute!important;inset:0;width:100%!important;height:100%!important;object-fit:contain;opacity:0}
.pet-visual[data-pet-id="pet_skipper"] .skipper-idle{opacity:1}
.roaming-pet .pet-visual[data-pet-id="pet_skipper"] .skipper-idle{animation:skipperIdleFrames 1.05s steps(1,end) infinite}
.roaming-pet .pet-visual[data-pet-id="pet_skipper"] .skipper-walk-one{animation:skipperWalkOne 1.05s steps(1,end) infinite}
.roaming-pet .pet-visual[data-pet-id="pet_skipper"] .skipper-walk-two{animation:skipperWalkTwo 1.05s steps(1,end) infinite}
@keyframes skipperIdleFrames{0%,15%,100%{opacity:1}16%,84%{opacity:0}}
@keyframes skipperWalkOne{0%,15%,49%,85%,100%{opacity:0}16%,48%{opacity:1}}
@keyframes skipperWalkTwo{0%,48%,84%,100%{opacity:0}49%,83%{opacity:1}}
@media (prefers-reduced-motion:reduce){.roaming-pet .pet-visual[data-pet-id="pet_skipper"] .skipper-frame{animation:none!important}.roaming-pet .pet-visual[data-pet-id="pet_skipper"] .skipper-idle{opacity:1}}


