to 12px;overflow:hidden;border:5px ridge #b78d4e;background-image:linear-gradient(0deg,rgba(8,6,9,.1),rgba(8,6,9,.05)),var(--watchcard-bg);background-size:cover;background-position:center 42%;box-shadow:0 8px 22px #000a}.party-pete-card-preview>img{position:absolute;z-index:1;left:50%;bottom:-9%;width:73%;height:90%;transform:translateX(-50%);object-fit:contain;object-position:center bottom;filter:drop-shadow(0 4px 2px #0008)}.party-pete-card-preview>span{position:absolute;z-index:2;left:0;right:0;bottom:0;padding:18px 8px 8px;background:linear-gradient(transparent,#09070be8);display:flex;flex-direction:column}.party-pete-card-preview small{color:#ffd463;font-size:9px}.party-pete-card-preview b{color:white;font-size:17px}.party-pete-confirm>p{margin:9px!important;font-size:15px!important;text-shadow:none!important}.party-pete-confirm>div:last-child{display:flex;justify-content:center;gap:9px}.party-pete-confirm button{margin:0!important}.party-pete-confirm button:disabled{opacity:.55;cursor:not-allowed}
