/* Equipped pet name tags inside fullscreen Quidditch Mode. */
#quidditchModePitch .qm-pet>.pet-label.has-custom-nametag{
  bottom:calc(100% + 6px)!important;
  filter:drop-shadow(0 2px 2px #000d)!important;
}
#quidditchModePitch .qm-pet>.pet-label.has-custom-nametag>.qm-custom-nametag{
  position:relative!important;
  display:block!important;
  width:150px!important;
  height:42px!important;
  margin:0 auto -5px!important;
  z-index:1!important;
  overflow:visible!important;
}
#quidditchModePitch .qm-pet>.pet-label.has-custom-nametag>.qm-custom-nametag>img{
  position:absolute!important;
  inset:0!important;
  width:100%!important;
  height:100%!important;
  object-fit:fill!important;
  image-rendering:pixelated!important;
  pointer-events:none!important;
}
#quidditchModePitch .qm-pet>.pet-label.has-custom-nametag>.qm-custom-nametag>b{
  position:absolute!important;
  left:var(--qm-tag-left,14%)!important;
  right:var(--qm-tag-right,10%)!important;
  top:50%!important;
  transform:translateY(-50%)!important;
  display:block!important;
  width:auto!important;
  max-width:none!important;
  margin:0!important;
  padding:0!important;
  border:0!important;
  border-radius:0!important;
  background:transparent!important;
  box-shadow:none!important;
  overflow:hidden!important;
  text-overflow:clip!important;
  white-space:nowrap!important;
  text-align:center!important;
  color:var(--qm-tag-text,#fff)!important;
  font-family:var(--qm-tag-font,Georgia,serif)!important;
  font-size:var(--qm-tag-size,8px)!important;
  font-weight:var(--qm-tag-weight,900)!important;
  line-height:1!important;
  letter-spacing:0!important;
  text-shadow:
    -1px -1px 0 var(--qm-tag-outline,#000),1px -1px 0 var(--qm-tag-outline,#000),
    -1px 1px 0 var(--qm-tag-outline,#000),1px 1px 0 var(--qm-tag-outline,#000),
    0 1px 2px #000!important;
}
#quidditchModePitch .qm-pet>.pet-label.has-custom-nametag>small{
  position:relative!important;
  z-index:2!important;
  margin-top:0!important;
}
