/* One-time Cloudflare launch tester reward */
.tester-reward-hello{position:fixed;z-index:1200;top:78px;left:14px;width:92px;height:102px;border:0;background:transparent;padding:0;cursor:pointer;filter:drop-shadow(0 5px 7px #000a);animation:testerHelloShake 2.8s ease-in-out infinite;transform-origin:50% 85%}
.tester-reward-hello img{display:block;width:100%;height:100%;object-fit:contain;transition:filter .2s ease,transform .2s ease}
.tester-reward-hello span{position:absolute;left:50%;bottom:-2px;transform:translateX(-50%);padding:2px 7px;border:1px solid #e7b754;background:#201306;color:#ffe9a4;font:900 10px Georgia,serif;letter-spacing:.08em;box-shadow:0 2px 5px #000b;white-space:nowrap}
.tester-reward-hello:hover img,.tester-reward-hello:focus-visible img{filter:brightness(1.28) drop-shadow(0 0 6px #fff4b8) drop-shadow(0 0 13px #ffc64d);transform:scale(1.06)}
.tester-reward-hello:hover{animation-duration:.55s}
@keyframes testerHelloShake{0%,72%,100%{transform:rotate(0deg)}76%{transform:rotate(-4deg)}80%{transform:rotate(4deg)}84%{transform:rotate(-3deg)}88%{transform:rotate(3deg)}92%{transform:rotate(0deg)}}
.tester-reward-dialog{border:0;background:transparent;padding:18px;max-width:min(960px,96vw);width:100%;overflow:visible}
.tester-reward-dialog::backdrop{background:rgba(5,3,1,.82);backdrop-filter:blur(3px)}
.tester-reward-panel{position:relative;border:2px solid #d89b27;background:linear-gradient(#251404,#100905);box-shadow:0 0 0 3px #4b2a0d,0 18px 60px #000;color:#ffe8a1;padding:26px;text-align:center;font-family:Georgia,serif}
.tester-reward-close{position:absolute;z-index:3;right:10px;top:8px;width:35px;height:35px;border:1px solid #d9a447;background:#241206;color:#ffeab0;font-size:25px;cursor:pointer}
.tester-reward-message-art{display:block;width:100%;height:auto;max-height:350px;object-fit:contain;margin:0 auto 18px}
.tester-reward-claim,.tester-reward-done{border:2px solid #f3c75f;background:linear-gradient(#8f531f,#4e270e);color:#fff1bd;padding:13px 30px;font:900 15px Georgia,serif;letter-spacing:.06em;cursor:pointer;box-shadow:inset 0 0 0 2px #291306,0 4px 10px #0009}
.tester-reward-claim:hover,.tester-reward-done:hover{filter:brightness(1.18);box-shadow:inset 0 0 0 2px #291306,0 0 18px #e6a63e88}
.tester-reward-claim:disabled{opacity:.55;cursor:wait}
.tester-reward-status{min-height:1.2em;margin:12px 0 0;color:#ffd786;font:700 13px Arial,sans-serif}
.tester-reward-success h2{margin:6px 0 8px;color:#fff0b2;text-shadow:0 2px 0 #5b2504;font-size:clamp(22px,4vw,38px)}
.tester-reward-success>p{font-size:18px;margin:8px 0 20px}
.tester-reward-prizes{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:0 0 22px}
.tester-reward-prizes>div{display:flex;min-height:120px;flex-direction:column;align-items:center;justify-content:center;gap:7px;border:1px solid #9b6826;background:#0d0906;padding:14px;box-shadow:inset 0 0 24px #71400d33}
.tester-reward-prizes strong{font-size:17px;color:#ffdc75}
.tester-reward-prizes small{font:12px Arial,sans-serif;color:#dbc99c}
.tester-reward-tag img{width:min(100%,260px);height:50px;object-fit:contain;margin-bottom:4px}
@media(max-width:700px){.tester-reward-hello{top:64px;left:5px;width:70px;height:82px}.tester-reward-panel{padding:18px 10px}.tester-reward-prizes{grid-template-columns:1fr}.tester-reward-message-art{margin-top:16px}}

/* ========================================================================== 
   PROFESSIONAL SKILL TREE — 2026-08-06
   A clearer progression hierarchy with a shared Harmony root and four branches.
   ========================================================================== */
#skillsDialog.game-dialog.wide {
  width: min(1180px, calc(100% - 28px));
  max-height: min(92vh, 980px);
  padding: 22px 24px 24px;
  overflow-x: hidden;
  overflow-y: auto;
  background:
    radial-gradient(circle at 50% -15%, rgba(191, 143, 48, .18), transparent 34%),
    linear-gradient(145deg, #17150f 0%, #0b0b09 48%, #080807 100%);
  border: 1px solid #a17731;
  box-shadow:
    inset 0 0 0 2px #241d11,
    inset 0 0 55px rgba(0,0,0,.72),
    0 24px 85px rgba(0,0,0,.82);
}

#skillsDialog::backdrop {
  background: rgba(2, 2, 2, .82);
  backdrop-filter: blur(4px);
}

#skillsDialog #skillsTitle {
  margin: 0 54px 18px;
  color: #f0cf7c;
  font: 800 25px/1.1 Georgia, serif;
  letter-spacing: 3px;
  text-align: center;
  text-shadow: 0 2px 0 #25170a, 0 0 20px rgba(217, 169, 66, .18);
}

#skillsDialog .dialog-x {
  top: 12px !important;
  right: 14px;
  width: 38px !important;
  height: 38px;
  display: grid;
  place-items: center;
  padding: 0 !important;
  border: 1px solid #5a4524 !important;
  border-radius: 6px;
  background: linear-gradient(#221c12, #100e0a) !important;
  color: #d8b867;
  transition: transform .18s ease, border-color .18s ease, color .18s ease, box-shadow .18s ease;
}

#skillsDialog .dialog-x:hover {
  color: #fff0b6;
  border-color: #b88b39 !important;
  box-shadow: 0 0 18px rgba(217, 168, 67, .24);
  transform: translateY(-1px);
}

#skillsDialog .skills-grid {
  display: block;
  width: 100%;
}

.skills-overview {
  display: grid;
  grid-template-columns: minmax(230px, 1.55fr) repeat(4, minmax(120px, .75fr));
  gap: 10px;
  padding: 12px;
  border: 1px solid #403522;
  border-radius: 9px;
  background: linear-gradient(180deg, rgba(42, 36, 24, .84), rgba(15, 14, 11, .94));
  box-shadow: inset 0 1px rgba(255,255,255,.035), 0 8px 28px rgba(0,0,0,.24);
}

.skills-overview-intro,
.skills-overview-stat {
  min-height: 82px;
  border: 1px solid rgba(115, 91, 48, .35);
  border-radius: 6px;
  background: linear-gradient(145deg, rgba(27, 25, 19, .95), rgba(11, 11, 9, .96));
}

.skills-overview-intro {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 13px 16px;
}

.skills-overview-intro > span {
  color: #8d7a53;
  font: 800 9px/1.1 system-ui, sans-serif;
  letter-spacing: 2.2px;
}

.skills-overview-intro > strong {
  margin-top: 4px;
  overflow: hidden;
  color: #eed38c;
  font: 800 22px/1.1 Georgia, serif;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.skills-overview-intro > small {
  margin-top: 5px;
  color: #928a78;
  font: 600 11px/1.25 system-ui, sans-serif;
}

.skills-overview-stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 10px;
  text-align: center;
}

.skills-overview-stat small {
  color: #81755e;
  font: 800 9px/1 system-ui, sans-serif;
  letter-spacing: 1.35px;
}

.skills-overview-stat b {
  max-width: 100%;
  margin-top: 7px;
  overflow: hidden;
  color: #f0cd73;
  font: 800 21px/1 Georgia, serif;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.skills-overview-stat span {
  margin-top: 4px;
  color: #aaa18d;
  font: 700 10px/1 system-ui, sans-serif;
}

.skills-tree-root {
  position: relative;
  width: min(500px, 92%);
  margin: 25px auto 0;
  padding-top: 15px;
}

.skills-root-crown {
  position: absolute;
  z-index: 2;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  padding: 5px 13px;
  border: 1px solid #967032;
  border-radius: 999px;
  background: #13110c;
  color: #cda957;
  font: 800 9px/1 system-ui, sans-serif;
  letter-spacing: 1.8px;
  white-space: nowrap;
  box-shadow: 0 0 0 4px #0d0d0a;
}

.skills-root-node {
  position: relative;
  display: grid;
  grid-template-columns: 98px minmax(0, 1fr);
  align-items: center;
  gap: 15px;
  min-height: 126px;
  padding: 20px 22px 17px;
  overflow: hidden;
  border: 1px solid #a17731;
  border-radius: 11px;
  background:
    radial-gradient(circle at 18% 50%, rgba(238, 190, 73, .19), transparent 29%),
    linear-gradient(135deg, #292315, #12110d 64%, #0a0a08);
  box-shadow:
    inset 0 0 0 2px rgba(59, 45, 23, .8),
    0 10px 35px rgba(0,0,0,.45),
    0 0 28px rgba(181, 133, 43, .12);
}

.skills-root-node::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(110deg, transparent 32%, rgba(255,255,255,.045) 48%, transparent 64%);
  transform: translateX(-100%);
  animation: skillRootSheen 5.8s ease-in-out infinite;
}

@keyframes skillRootSheen {
  0%, 64% { transform: translateX(-100%); }
  84%, 100% { transform: translateX(100%); }
}

.skills-root-icon {
  position: relative;
  display: grid;
  place-items: center;
  width: 86px;
  height: 86px;
  border: 1px solid #a67c35;
  border-radius: 50%;
  background: radial-gradient(circle, #342b17, #12100b 68%);
  box-shadow: inset 0 0 16px rgba(221, 174, 64, .18), 0 0 20px rgba(205, 157, 55, .12);
}

.skills-root-icon img {
  width: 64px;
  height: 64px;
  object-fit: contain;
  filter: drop-shadow(0 4px 4px #000);
}

.skills-root-icon span {
  position: absolute;
  right: -6px;
  bottom: -4px;
  display: grid;
  place-items: center;
  min-width: 31px;
  height: 31px;
  padding: 0 4px;
  border: 2px solid #c4933f;
  border-radius: 50%;
  background: #0d0c09;
  color: #f3d278;
  font: 900 14px/1 Georgia, serif;
  box-shadow: 0 3px 10px #000;
}

.skills-root-copy > div:first-child {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
}

.skills-root-copy b {
  color: #f2d17a;
  font: 800 25px/1 Georgia, serif;
}

.skills-root-copy em {
  color: #aa8e50;
  font: 800 9px/1 system-ui, sans-serif;
  letter-spacing: 1.2px;
  text-transform: uppercase;
}

.skills-root-copy > strong {
  display: block;
  margin-top: 7px;
  color: #bcb39f;
  font: 700 12px/1 system-ui, sans-serif;
}

.skills-root-progress,
.skill-node-progress {
  overflow: hidden;
  border: 1px solid rgba(92, 75, 43, .68);
  background: #050505;
  box-shadow: inset 0 1px 3px #000;
}

.skills-root-progress {
  height: 9px;
  margin-top: 9px;
  border-radius: 999px;
}

.skills-root-progress i,
.skill-node-progress i {
  display: block;
  height: 100%;
  background: linear-gradient(90deg, #7b4b12, #d8a537 72%, #f3d27b);
  box-shadow: inset 0 1px rgba(255,255,255,.25), 0 0 12px rgba(217, 166, 56, .24);
}

.skills-root-copy > small {
  display: block;
  margin-top: 7px;
  color: #8f8878;
  font: 700 10px/1.2 system-ui, sans-serif;
}

.skills-tree-connector {
  position: relative;
  width: 74%;
  height: 32px;
  margin: 0 auto;
  border-bottom: 1px solid rgba(132, 101, 45, .65);
}

.skills-tree-connector::before {
  content: "";
  position: absolute;
  top: 0;
  left: 50%;
  width: 1px;
  height: 100%;
  background: linear-gradient(#a87c31, #6f552b);
}

.skills-tree-branches {
  position: relative;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
  margin-top: 14px;
}

.skill-branch {
  --branch-rgb: 176, 143, 72;
  --branch-bright: #c9aa61;
  position: relative;
  padding: 12px;
  border: 1px solid rgba(var(--branch-rgb), .38);
  border-radius: 9px;
  background:
    linear-gradient(180deg, rgba(var(--branch-rgb), .07), transparent 42%),
    linear-gradient(145deg, rgba(24, 23, 19, .97), rgba(10, 10, 8, .98));
  box-shadow: inset 0 1px rgba(255,255,255,.025), 0 7px 24px rgba(0,0,0,.24);
}

.skill-branch::before {
  content: "";
  position: absolute;
  top: -15px;
  left: 50%;
  width: 1px;
  height: 15px;
  background: rgba(var(--branch-rgb), .55);
}

.skill-branch-gathering { --branch-rgb: 87, 142, 76; --branch-bright: #8fc278; }
.skill-branch-combat { --branch-rgb: 165, 72, 69; --branch-bright: #d4837e; }
.skill-branch-artisan { --branch-rgb: 101, 119, 172; --branch-bright: #91a3df; }
.skill-branch-adventure { --branch-rgb: 153, 105, 170; --branch-bright: #c291d4; }

.skill-branch-header {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  margin-bottom: 10px;
  padding: 2px 3px 10px;
  border-bottom: 1px solid rgba(var(--branch-rgb), .28);
}

.skill-branch-symbol {
  display: grid;
  place-items: center;
  width: 31px;
  height: 31px;
  border: 1px solid rgba(var(--branch-rgb), .55);
  border-radius: 6px;
  background: rgba(var(--branch-rgb), .09);
  color: var(--branch-bright);
  font: 800 16px/1 Georgia, serif;
}

.skill-branch-header > div {
  min-width: 0;
}

.skill-branch-header b {
  display: block;
  color: var(--branch-bright);
  font: 800 16px/1.1 Georgia, serif;
  letter-spacing: .5px;
}

.skill-branch-header small {
  display: block;
  margin-top: 3px;
  overflow: hidden;
  color: #817d72;
  font: 650 10px/1.1 system-ui, sans-serif;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.skill-branch-header > strong {
  min-width: 42px;
  color: rgba(var(--branch-rgb), .95);
  font: 800 20px/1 Georgia, serif;
  text-align: right;
}

.skill-branch-nodes {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.skill-tree-node {
  display: grid;
  grid-template-columns: 61px minmax(0, 1fr);
  align-items: center;
  gap: 10px;
  min-height: 88px;
  padding: 9px 10px;
  border: 1px solid rgba(var(--branch-rgb), .25);
  border-radius: 7px;
  background: linear-gradient(145deg, rgba(31, 30, 25, .95), rgba(12, 12, 10, .98));
  box-shadow: inset 0 1px rgba(255,255,255,.025), 0 3px 8px rgba(0,0,0,.2);
  transition: transform .18s ease, border-color .18s ease, background .18s ease, box-shadow .18s ease;
}

.skill-tree-node:hover {
  z-index: 2;
  transform: translateY(-2px);
  border-color: rgba(var(--branch-rgb), .68);
  background: linear-gradient(145deg, rgba(var(--branch-rgb), .11), rgba(15, 15, 12, .98));
  box-shadow: 0 8px 22px rgba(0,0,0,.32), 0 0 18px rgba(var(--branch-rgb), .08);
}

.skill-node-icon {
  position: relative;
  display: grid;
  place-items: center;
  width: 56px;
  height: 56px;
  border: 1px solid rgba(var(--branch-rgb), .45);
  border-radius: 50%;
  background: radial-gradient(circle, rgba(var(--branch-rgb), .12), #0b0b09 72%);
}

.skill-node-icon img {
  width: 43px;
  height: 43px;
  object-fit: contain;
  filter: drop-shadow(0 3px 3px #000);
}

.skill-node-icon span {
  position: absolute;
  right: -4px;
  bottom: -4px;
  display: grid;
  place-items: center;
  min-width: 25px;
  height: 25px;
  padding: 0 3px;
  border: 1px solid rgba(var(--branch-rgb), .75);
  border-radius: 50%;
  background: #0b0b09;
  color: var(--branch-bright);
  font: 900 11px/1 Georgia, serif;
  box-shadow: 0 2px 8px #000;
}

.skill-node-details {
  min-width: 0;
}

.skill-node-title {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 7px;
}

.skill-node-title b {
  overflow: hidden;
  color: #d9cfb7;
  font: 800 13px/1.1 Georgia, serif;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.skill-node-title em {
  flex: 0 0 auto;
  color: rgba(var(--branch-rgb), .8);
  font: 800 9px/1 system-ui, sans-serif;
}

.skill-node-details > small {
  display: block;
  margin-top: 4px;
  color: #8c8679;
  font: 700 9px/1 system-ui, sans-serif;
}

.skill-node-progress {
  height: 6px;
  margin-top: 7px;
  border-radius: 999px;
}

.skill-node-progress i {
  background: linear-gradient(90deg, rgba(var(--branch-rgb), .65), var(--branch-bright));
  box-shadow: inset 0 1px rgba(255,255,255,.18), 0 0 8px rgba(var(--branch-rgb), .16);
}

.skill-node-next {
  display: block;
  margin-top: 5px;
  overflow: hidden;
  color: #777267;
  font: 650 8px/1 system-ui, sans-serif;
  letter-spacing: .1px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.skill-tree-node.is-maxed,
.skills-root-node.is-maxed {
  border-color: #d6aa49;
  box-shadow: inset 0 0 18px rgba(220, 174, 69, .07), 0 0 18px rgba(220, 174, 69, .08);
}

.skill-tree-node.is-maxed .skill-node-icon {
  box-shadow: inset 0 0 12px rgba(235, 190, 82, .14), 0 0 12px rgba(224, 177, 69, .11);
}

#skillsDialog .skills-leaderboard-button,
#skillsDialog .change-character {
  min-width: 190px;
  min-height: 45px;
  margin-top: 18px;
  border: 1px solid #72572c;
  border-radius: 6px;
  background: linear-gradient(#2d2517, #15120d);
  color: #d8bc74;
  font: 900 11px/1 system-ui, sans-serif;
  letter-spacing: 1px;
  box-shadow: inset 0 1px rgba(255,255,255,.04), 0 4px 12px rgba(0,0,0,.24);
  transition: transform .16s ease, border-color .16s ease, color .16s ease, box-shadow .16s ease;
}

#skillsDialog .skills-leaderboard-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

#skillsDialog .change-character {
  float: right;
  color: #b99a67;
}

#skillsDialog .skills-leaderboard-button:hover,
#skillsDialog .change-character:hover {
  transform: translateY(-1px);
  border-color: #b78a3c;
  color: #ffe7a4;
  box-shadow: 0 7px 18px rgba(0,0,0,.34), 0 0 16px rgba(202, 152, 55, .1);
}

#skillsDialog::-webkit-scrollbar { width: 10px; }
#skillsDialog::-webkit-scrollbar-track { background: #080807; }
#skillsDialog::-webkit-scrollbar-thumb { border: 2px solid #080807; border-radius: 999px; background: #584423; }
#skillsDialog::-webkit-scrollbar-thumb:hover { background: #80612f; }

@media (max-width: 980px) {
  .skills-overview {
    grid-template-columns: repeat(4, 1fr);
  }
  .skills-overview-intro {
    grid-column: 1 / -1;
    min-height: 66px;
  }
  .skill-branch-nodes {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 760px) {
  #skillsDialog.game-dialog.wide {
    width: calc(100% - 14px);
    max-height: 95vh;
    padding: 18px 12px 20px;
  }
  #skillsDialog #skillsTitle {
    margin-bottom: 14px;
    font-size: 19px;
    letter-spacing: 1.5px;
  }
  .skills-overview {
    grid-template-columns: repeat(2, 1fr);
  }
  .skills-overview-intro {
    grid-column: 1 / -1;
  }
  .skills-tree-root {
    width: 100%;
  }
  .skills-root-node {
    grid-template-columns: 75px minmax(0, 1fr);
    gap: 11px;
    min-height: 108px;
    padding: 18px 14px 14px;
  }
  .skills-root-icon {
    width: 68px;
    height: 68px;
  }
  .skills-root-icon img {
    width: 51px;
    height: 51px;
  }
  .skills-root-copy b {
    font-size: 21px;
  }
  .skills-tree-connector {
    display: none;
  }
  .skills-tree-branches {
    grid-template-columns: 1fr;
    margin-top: 14px;
  }
  .skill-branch::before {
    display: none;
  }
  #skillsDialog .skills-leaderboard-button,
  #skillsDialog .change-character {
    width: 100%;
    float: none;
    margin-top: 10px;
  }
}

@media (max-width: 430px) {
  .skills-overview-stat {
    min-height: 70px;
  }
  .skills-overview-stat b {
    font-size: 18px;
  }
  .skills-root-copy > div:first-child {
    display: block;
  }
  .skills-root-copy em {
    display: block;
    margin-top: 4px;
  }
  .skill-tree-node {
    grid-template-columns: 54px minmax(0, 1fr);
    min-height: 82px;
    padding: 8px;
  }
  .skill-node-icon {
    width: 49px;
    height: 49px;
  }
  .skill-node-icon img {
    width: 37px;
    height: 37px;
  }
}

/* =========================================================
   PROFESSIONAL RUNECRAFTING MODE CARDS + SHOOTING STAR 2.0
   ========================================================= */

/* Keep both Runecrafting activity buttons perfectly matched. */
.runecrafting-dialog #rcModeHub.rc-mode-hub{
  display:grid!important;
  grid-template-columns:1fr!important;
  grid-auto-rows:138px!important;
  gap:12px!important;
  margin-top:16px!important;
}
.runecrafting-dialog #rcModeHub .rc-mode-card{
  position:relative!important;
  width:100%!important;
