/* ========================================================================
   RCG SLAB BINDER v21.30 — PREMIUM GAME-GRADE PERSONALITY EFFECTS
   Layered atmosphere, theme-coloured edge lighting and high-detail particles.
   ======================================================================== */

#repoRcgBinderDialog[data-rcg-upgrade-effect]{
  --rcgfx1:var(--rcgu-c);
  --rcgfx2:var(--rcgu-a);
  --rcgfx3:#d8ad58;
  --rcgfxGlow:color-mix(in srgb,var(--rcgfx1) 42%,transparent);
}
#repoRcgBinderDialog[data-rcg-upgrade-effect='inferno']{--rcgfx1:#ffb448;--rcgfx2:#ff4e16;--rcgfx3:#8d1609}
#repoRcgBinderDialog[data-rcg-upgrade-effect='celestial']{--rcgfx1:#b99cff;--rcgfx2:#4d9dff;--rcgfx3:#f2f5ff}
