#repoRcgBinderDialog[data-rcg-upgrade-effect='voidrift']{--rcgfx1:#d29cff;--rcgfx2:#7635da;--rcgfx3:#231052}
#repoRcgBinderDialog[data-rcg-upgrade-effect='enchantedwilds']{--rcgfx1:#baf49d;--rcgfx2:#40b86b;--rcgfx3:#16603b}
