/* The whole binder now takes on the personality of its selected animation. */
#repoRcgBinderDialog[data-rcg-upgrade-effect]:not([data-rcg-upgrade-effect='calm']) .repo-rcg-v2118-book{
  box-shadow:
    0 28px 50px rgba(0,0,0,.66),
    0 0 42px color-mix(in srgb,var(--rcgfx1) 20%,transparent),
    0 0 100px color-mix(in srgb,var(--rcgfx2) 10%,transparent),
    inset 0 0 0 2px rgba(204,155,63,.82),
    inset 0 0 0 6px var(--rcgu-deep),
    inset 0 0 42px color-mix(in srgb,var(--rcgfx2) 23%,transparent)!important;
}
#repoRcgBinderDialog[data-rcg-upgrade-effect]:not([data-rcg-upgrade-effect='calm']) .repo-rcg-v2118-page{
  box-shadow:
    inset 0 0 0 3px var(--rcgu-deep),
    inset 0 0 24px color-mix(in srgb,var(--rcgfx2) 18%,rgba(0,0,0,.35)),
    0 0 18px color-mix(in srgb,var(--rcgfx1) 10%,transparent)!important;
}
#repoRcgBinderDialog[data-rcg-upgrade-effect]:not([data-rcg-upgrade-effect='calm']) .repo-rcg-v2118-spine-plaque i{
  background:linear-gradient(135deg,var(--rcgfx1),var(--rcgfx2))!important;
  box-shadow:0 0 7px var(--rcgfx1),0 0 20px color-mix(in srgb,var(--rcgfx2) 48%,transparent)!important;
}

/* Layer stack lives behind slabs but above the page artwork. */
#repoRcgBinderDialog .repo-rcg-upgrade-fx-v2129{
  inset:.7%!important;
  z-index:5!important;
  opacity:1!important;
  overflow:hidden!important;
  border-radius:13px!important;
  mix-blend-mode:screen!important;
  isolation:isolate!important;
}
