  width:3px!important;height:3px!important;
  border-radius:50%!important;
  background:var(--rcgfx1)!important;
  box-shadow:0 0 7px var(--rcgfx1),0 0 14px color-mix(in srgb,var(--rcgfx2) 55%,transparent)!important;
  opacity:.72!important;
  animation:repoRcgPremiumFloatV2130 calc(var(--s) * .085s) linear calc(var(--n) * -.23s) infinite!important;
}

